import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.Blackhole;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.ReentrantLock;

@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 10, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(value = 2, jvmArgs = {"-Xms4g", "-Xmx4g", "-XX:+UseG1GC"})
@State(Scope.Benchmark)
public class ConcurrencyPrimitiveBenchmark {
    private AtomicLong atomicCounter;
    private ReentrantLock lock;
    private long bareCounter;

    @Setup(Level.Trial)
    public void setup() {
        atomicCounter = new AtomicLong(0);
        lock = new ReentrantLock();
        bareCounter = 0L;
    }

    @Benchmark
    @Threads(8)
    public long testAtomicIncrement() {
        return atomicCounter.incrementAndGet();
    }

    @Benchmark
    @Threads(8)
    public long testLockProtectedIncrement() {
        lock.lock();
        try {
            bareCounter++;
            return bareCounter;
        } finally {
            lock.unlock();
        }
    }

    @Benchmark
    @Threads(8)
    public void testBlackholeConsumption(Blackhole bh) {
        long current = atomicCounter.get();
        long transformed = current * 31L + 17L;
        bh.consume(transformed);
    }
}

public class NetworkDataService {
    // ANTI-PATTERN: Synchronized monitor pins virtual thread to carrier during blocking socket reads
    public synchronized String blockingFetchOverMonitor(Socket socket) throws IOException {
        InputStream in = socket.getInputStream();
        byte[] buffer = new byte[1024];
        int read = in.read(buffer);
        return new String(buffer, 0, read, StandardCharsets.UTF_8);
    }

    // PRODUCTION RECTIFICATION: ReentrantLock yields carrier thread cleanly
    private final ReentrantLock lock = new ReentrantLock();

    public String nonPinningFetch(Socket socket) throws IOException {
        lock.lock();
        try {
            InputStream in = socket.getInputStream();
            byte[] buffer = new byte[1024];
            int read = in.read(buffer);
            return new String(buffer, 0, read, StandardCharsets.UTF_8);
        } finally {
            lock.unlock();
        }
    }
}

package com.architect.concurrency;

import java.lang.invoke.MethodHandles;
import java.lang.invoke.VarHandle;

public class LockFreeNodeStack<T> {
    public static class Node<T> {
        final T value;
        Node<T> next;
        public Node(T value) { this.value = value; }
    }

    private volatile Node<T> head;
    private static final VarHandle HEAD_HANDLE;

    static {
        try {
            HEAD_HANDLE = MethodHandles.lookup()
                .findVarHandle(LockFreeNodeStack.class, "head", Node.class);
        } catch (ReflectiveOperationException e) {
            throw new ExceptionInInitializerError(e);
        }
    }

    public void push(T item) {
        Node<T> newHead = new Node<>(item);
        while (true) {
            Node<T> currentHead = (Node<T>) HEAD_HANDLE.getAcquire(this);
            newHead.next = currentHead;
            if (HEAD_HANDLE.compareAndSet(this, currentHead, newHead)) {
                return;
            }
            Thread.onSpinWait();
        }
    }

    public T pop() {
        while (true) {
            Node<T> currentHead = (Node<T>) HEAD_HANDLE.getAcquire(this);
            if (currentHead == null) {
                return null;
            }
            Node<T> nextNode = currentHead.next;
            if (HEAD_HANDLE.compareAndSet(this, currentHead, nextNode)) {
                return currentHead.value;
            }
            Thread.onSpinWait();
        }
    }
}

package com.architect.disruptor;

class LhsPadding {
    protected long p1, p2, p3, p4, p5, p6, p7;
}

class ValueHolder extends LhsPadding {
    protected volatile long value = 0;
}

class RhsPadding extends ValueHolder {
    protected long p9, p10, p11, p12, p13, p14, p15;
}

public class PaddedAtomicSequence extends RhsPadding {
    public PaddedAtomicSequence(long initialValue) {
        this.value = initialValue;
    }
    public long get() { return value; }
    public void set(long value) { this.value = value; }
    public long sumToPreventOptimization() {
        return p1 + p2 + p3 + p4 + p5 + p6 + p7 + p9 + p10 + p11 + p12 + p13 + p14 + p15;
    }
}

