public class ParameterPassingDemonstration {
    static class DataContainer {
        int value;
        DataContainer(int value) { this.value = value; }
    }

    public static void executeLifecycle(DataContainer container, int primitiveVal) {
        // 1. Mutate internal state (Visible to caller via shared heap object)
        container.value = 20;

        // 2. Mutate primitive copy (Invisible to caller; isolated stack slot)
        primitiveVal = 999;

        // 3. Reassign local reference pointer (Invisible to caller)
        container = new DataContainer(5555);
        container.value = 8888;
    }

    public static void main(String[] args) {
        DataContainer mainContainer = new DataContainer(10);
        int mainPrimitive = 100;
        executeLifecycle(mainContainer, mainPrimitive);
        System.out.println("Container value: " + mainContainer.value); // Prints 20
        System.out.println("Primitive value: " + mainPrimitive); // Prints 100
    }
}

