import functools
import time

# Part A: Parameterized Decorator for Execution Timing
def time_execution(threshold_seconds=0.05):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            start_time = time.perf_counter()
            result = func(*args, **kwargs)
            duration = time.perf_counter() - start_time
            if duration > threshold_seconds:
                print(f"[WARNING] {func.__name__} took {duration:.4f}s (Threshold: {threshold_seconds}s)")
            return result
        return wrapper
    return decorator

@time_execution(threshold_seconds=0.01)
def slow_calculation():
    time.sleep(0.02)
    return "Done"

slow_calculation()

# Part B: Class-Based Call Counter Decorator
class CallCounter:
    def __init__(self, func):
        self.func = func
        self.count = 0
        functools.update_wrapper(self, func)

    def __call__(self, *args, **kwargs):
        self.count += 1
        print(f"Function '{self.func.__name__}' called {self.count} times")
        return self.func(*args, **kwargs)

@CallCounter
def greet(name):
    return f"Hello, {name}"

greet("Alice")
greet("Bob")

# Part A: Custom Exception with Explicit Chaining
class ValidationError(Exception):
    pass

def process_age(age_str):
    try:
        age = int(age_str)
        if age < 0:
            raise ValueError("Age cannot be negative")
        return age
    except ValueError as err:
        # Explicit exception chaining
        raise ValidationError("Invalid age input provided") from err

try:
    process_age("-5")
except ValidationError as e:
    print("Caught Exception:", e)
    print("Original Cause: ", e.__cause__)

