# Part A: Stage 1 (__new__) and Stage 2 (__init__)
class LifecycleDemo:
    def __new__(cls, *args, **kwargs):
        print("1. __new__ called: Allocating memory for PyObject")
        instance = super().__new__(cls)
        return instance

    def __init__(self, name):
        print("2. __init__ called: Initializing object state")
        self.name = name

obj = LifecycleDemo("Sample")

# Part B: Memory Optimization with __slots__
class SlottedPoint:
    __slots__ = ("x", "y") # Replaces __dict__ with fixed pointer array

    def __init__(self, x, y):
        self.x = x
        self.y = y

p = SlottedPoint(10, 20)
print(f"Point: x={p.x}, y={p.y}")

