# Part B: MRO and Cooperative super() Calls
class Base:
    def action(self):
        print("Base execution")

class MixinA(Base):
    def action(self):
        print("MixinA start")
        super().action()
        print("MixinA end")

class MixinB(Base):
    def action(self):
        print("MixinB start")
        super().action()
        print("MixinB end")

class Combined(MixinA, MixinB):
    pass

c = Combined()
print("MRO Sequence:", [cls.__name__ for cls in Combined.__mro__])
c.action()

class Vector:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    # Technical String Representation
    def __repr__(self):
        return f"Vector({self.x}, {self.y})"

    # Overloading + Operator
    def __add__(self, other):
        if isinstance(other, Vector):
            return Vector(self.x + other.x, self.y + other.y)
        return NotImplemented

    # Overloading Indexing (v[0], v[1])
    def __getitem__(self, index):
        if index == 0: return self.x
        if index == 1: return self.y
        raise IndexError("Vector index out of range")

    # Fallback Attribute Access
    def __getattr__(self, name):
        return f"Attribute '{name}' does not exist"

v1 = Vector(2, 3)
v2 = Vector(4, 5)

print("Vector Addition (v1 + v2):", v1 + v2) # Output: Vector(6, 8)
print("Vector Index 0 (v1[0]):    ", v1[0])    # Output: 2
print("Missing Attribute:        ", v1.z)      # Output: Attribute 'z' does not exist

class IntegerField:
    def __init__(self, name):
        self.storage_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self # Accessed via class object
        return getattr(instance, self.storage_name, 0)

    def __set__(self, instance, value):
        if not isinstance(value, int):
            raise TypeError(f"Field '{self.storage_name}' must be an integer")
        setattr(instance, self.storage_name, value)

class Player:
    score = IntegerField("score") # Data descriptor instance

p = Player()
p.score = 100 # Invokes IntegerField.__set__
print("Player Score:", p.score) # Invokes IntegerField.__get__

try:
    p.score = "One Hundred"
except TypeError as err:
    print("Descriptor Blocked Value:", err)

# Part A: Metaclass enforcing upper-case attribute names
class EnforceUppercaseMeta(type):
    def __new__(mcs, name, bases, attrs):
        # Validate that non-dunder attributes are uppercase
        for attr_name in attrs:
            if not attr_name.startswith("_") and not attr_name.isupper():
                raise TypeError(f"Attribute '{attr_name}' in '{name}' must be uppercase!")
        return super().__new__(mcs, name, bases, attrs)

class SystemConfig(metaclass=EnforceUppercaseMeta):
    PORT = 8080
    HOST = "127.0.0.1"
    # timeout = 30 # Uncommenting raises TypeError!

print("SystemConfig Host:", SystemConfig.HOST)

# Part B: Class Registration via __init_subclass__
class PluginBase:
    registry = {}
    def __init_subclass__(cls, plugin_name, **kwargs):
        super().__init_subclass__(**kwargs)
        cls.registry[plugin_name] = cls

class AudioPlugin(PluginBase, plugin_name="audio_processor"):
    pass

print("Registered Plugins:", PluginBase.registry)

from typing import TypeVar, Generic, Protocol

# Part A: Generics with TypeVar
T = TypeVar("T")

class Container(Generic[T]):
    def __init__(self, item: T):
        self._item = item

    def get_item(self) -> T:
        return self._item

int_box = Container[int](100)
str_box = Container[str]("Python")
print("Int Box Item:", int_box.get_item())

# Part B: Structural Subtyping with Protocol
class Renderable(Protocol):
    def render(self) -> str:
        ...

class Button:
    def render(self) -> str:
        return "<button>Click</button>"

def draw_element(element: Renderable) -> None:
    print("Rendering:", element.render())

draw_element(Button()) # Matches Protocol interface statically
